alter table public.profiles enable row level security; alter table public.businesses enable row level security; alter table public.business_members enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.customers enable row level security; alter table public.sales enable row level security; alter table public.sale_items enable row level security; alter table public.inventory_movements enable row level security; alter table public.business_settings enable row level security;
create policy profiles_self on public.profiles for select using (id=auth.uid());
create policy business_member_access on public.businesses for select using (public.is_business_member(id)); create policy business_admin_update on public.businesses for update using (public.can_write_business(id));
create policy members_same_business on public.business_members for select using (public.is_business_member(business_id));
create policy categories_member on public.categories for select using (public.is_business_member(business_id)); create policy categories_write on public.categories for all using (public.can_write_business(business_id)) with check (public.can_write_business(business_id));
create policy products_member on public.products for select using (public.is_business_member(business_id)); create policy products_write on public.products for all using (public.can_write_business(business_id)) with check (public.can_write_business(business_id));
create policy customers_member on public.customers for select using (public.is_business_member(business_id)); create policy customers_write on public.customers for all using (public.can_write_business(business_id)) with check (public.can_write_business(business_id));
create policy sales_member on public.sales for select using (public.is_business_member(business_id)); create policy sales_write on public.sales for insert with check (public.can_write_business(business_id));
create policy sale_items_member on public.sale_items for select using (exists(select 1 from public.sales s where s.id=sale_id and public.is_business_member(s.business_id)));
create policy movements_member on public.inventory_movements for select using (public.is_business_member(business_id)); create policy movements_write on public.inventory_movements for insert with check (public.can_write_business(business_id));
create policy settings_member on public.business_settings for select using (public.is_business_member(business_id)); create policy settings_write on public.business_settings for all using (public.can_write_business(business_id)) with check (public.can_write_business(business_id));
